INSERT OR IGNORE INTO forms (id, data, client_id, template, updated_at) VALUES ('landing-demo', '{"id":"landing-demo","name":"Landing demo","clientId":"test-landing-page","template":"custom-enquiry","brand":{"name":"JewelryLead"},"theme":{"accent":"#35d0c4","accent-ink":"#032220","bg":"#070b0c","surface":"#10171a","surface-2":"#152024","line":"#1f2c30","line-strong":"#34464b","ink":"#eef6f5","ink-soft":"#9fb3b1","ink-faint":"#627674"},"maxRenders":4,"background":"deep charcoal black","contact":{"title":"Your design is ready to render","subtitle":"Where should we send your preview and follow up with a quote?","consent":"I agree to be contacted about my design by JewelryLead by email, phone or text. Message and data rates may apply.","button":"Reveal my design"},"result":{"loading":["Sketching your piece","Choosing the metal","Setting the stones","Polishing the details","Adjusting the light"],"done":"Our team will reach out within 24 hours with a quote.","disclaimer":"AI concept preview. Your final piece is handcrafted and may differ in detail."},"styles":{"pendant":[{"value":"script","label":"Script name","image":"/library/pendant/script.webp","shape":"a cursive script name-plate pendant: one connected word in flowing joined script letters, hung from the chain by a bail"},{"value":"block","label":"Block letters","image":"/library/pendant/block.webp","shape":"a bold block-letter name pendant: thick upright capital letters joined side by side into one solid plate"},{"value":"medallion","label":"Medallion","image":"/library/pendant/medallion.webp","shape":"a round medallion pendant with a raised decorative border frame around a flat circular center"},{"value":"cross","label":"Cross","image":"/library/pendant/cross.webp","shape":"a cross pendant with straight even arms and slightly flared ends"}],"chain":[{"value":"cuban","label":"Miami Cuban","image":"/library/chain/cuban.webp","shape":"a Miami Cuban link chain: thick, tightly interlocking flattened oval links and a rectangular box clasp"},{"value":"rope","label":"Rope","image":"/library/chain/rope.webp","shape":"a rope chain: small links twisted together so the chain looks like a twisted rope"},{"value":"tennis","label":"Tennis","image":"/library/chain/tennis.webp","shape":"a tennis chain: one continuous line of individual round stones, each in its own small prong setting"},{"value":"franco","label":"Franco","image":"/library/chain/franco.webp","shape":"a Franco chain: dense V-shaped links forming a square, braided-looking profile"}],"ring":[{"value":"solitaire","label":"Solitaire","image":"/library/ring/solitaire.webp","shape":"a solitaire ring: one single center stone raised in a prong setting on a slim band"},{"value":"halo","label":"Halo","image":"/library/ring/halo.webp","shape":"a halo ring: a center stone surrounded by a tight circle of small stones"},{"value":"three-stone","label":"Three stone","image":"/library/ring/three-stone.webp","shape":"a three-stone ring: a larger center stone flanked by two smaller side stones in a row"},{"value":"eternity","label":"Eternity band","image":"/library/ring/eternity.webp","shape":"an eternity band: a continuous row of equal stones set all the way around the band, no center stone"},{"value":"signet","label":"Signet","image":"/library/ring/signet.webp","shape":"a signet ring: a heavy band with a flat oval top surface"}],"grillz":[{"value":"top6","label":"Top 6","image":"/library/grillz/top6.webp","shape":"a single top grill covering exactly the six upper front teeth, in ONE row only, no bottom row"},{"value":"top8","label":"Top 8","image":"/library/grillz/top8.webp","shape":"a single top grill covering exactly eight upper teeth, in ONE row only, no bottom row"},{"value":"set","label":"Top + bottom","image":"/library/grillz/set.webp","shape":"a matching grillz set: a top row of eight teeth and a bottom row of eight teeth"},{"value":"fangs","label":"Fangs","image":"/library/grillz/fangs.webp","shape":"two separate fang caps for the upper canine teeth, pointed and elongated"}],"bracelet":[{"value":"cuban","label":"Cuban","image":"/library/bracelet/cuban.webp","shape":"a Cuban link bracelet: thick interlocking flattened oval links and a box clasp"},{"value":"tennis","label":"Tennis","image":"/library/bracelet/tennis.webp","shape":"a tennis bracelet: one continuous line of individual round stones in small prong settings"},{"value":"bangle","label":"Bangle","image":"/library/bracelet/bangle.webp","shape":"a rigid bangle: one solid smooth round band with a hinge clasp"}],"earrings":[{"value":"studs","label":"Studs","image":"/library/earrings/studs.webp","shape":"stud earrings: a single stone or shape sitting directly on the earlobe, no drop"},{"value":"drops","label":"Drops","image":"/library/earrings/drops.webp","shape":"drop earrings: a small top stud with a pendant element hanging below it"},{"value":"hoops","label":"Hoops","image":"/library/earrings/hoops.webp","shape":"hoop earrings: round open hoops"}],"watch":[{"value":"iced","label":"Fully iced","image":"/library/watch/iced.webp","shape":"a fully iced watch with a round case: stones covering the case, bezel, bracelet and the entire dial"},{"value":"bezel","label":"Iced bezel","image":"/library/watch/bezel.webp","shape":"a watch with only the bezel set with stones; clean dial and plain polished link bracelet"}]},"steps":[{"id":"type","label":"Piece","title":"What are we creating?","subtitle":"Pick the piece you have in mind.","autoAdvance":true,"enabled":true,"fields":[{"id":"type","type":"cards","required":true,"builtin":true,"options":[{"value":"pendant","label":"Pendant","icon":"pendant"},{"value":"chain","label":"Chain","icon":"chain"},{"value":"ring","label":"Ring","icon":"ring"},{"value":"grillz","label":"Grillz","icon":"grillz"},{"value":"bracelet","label":"Bracelet","icon":"bracelet"},{"value":"earrings","label":"Earrings","icon":"earrings"},{"value":"watch","label":"Watch","icon":"watch"}]}]},{"id":"style","label":"Style","title":"Choose a style","subtitle":"Pick the shape closest to your idea. We customize everything from there.","autoAdvance":true,"fields":[{"id":"style","type":"cards","required":true,"builtin":true,"optionsFrom":{"field":"type","styles":true}}]},{"id":"teeth","label":"Teeth","title":"Select your teeth","subtitle":"How many teeth do you want? Tap a tooth or pick a set.","fields":[{"id":"teeth","type":"teeth","required":true,"builtin":true,"showIf":{"field":"type","in":["grillz"]}}]},{"id":"design","label":"Design","title":"Metal & stones","subtitle":"The materials that set the tone.","fields":[{"id":"metal","type":"chips","label":"Metal","required":true,"builtin":true,"options":[{"value":"yellow-gold","label":"Yellow Gold","swatch":"#e2b04a"},{"value":"white-gold","label":"White Gold","swatch":"#e6e6e3"},{"value":"rose-gold","label":"Rose Gold","swatch":"#d99a86"},{"value":"platinum","label":"Platinum","swatch":"#c9ccd1"},{"value":"two-tone","label":"Two-Tone","swatch":"linear-gradient(135deg,#e2b04a 50%,#e6e6e3 50%)"}]},{"id":"karat","type":"chips","label":"Karat","required":true,"builtin":true,"showIf":{"field":"metal","notIn":["platinum"]},"options":[{"value":"10K","label":"10K"},{"value":"14K","label":"14K"},{"value":"18K","label":"18K"},{"value":"925 Silver","label":"925 Silver"}]},{"id":"stones","type":"chips","label":"Stones","required":true,"builtin":true,"options":[{"value":"none","label":"No stones"},{"value":"moissanite","label":"Moissanite"},{"value":"lab","label":"Lab-grown diamonds"},{"value":"natural","label":"Natural diamonds"}]},{"id":"coverage","type":"chips","label":"How iced?","required":true,"builtin":true,"showIf":{"field":"stones","notIn":["none"]},"options":[{"value":"accents","label":"Accents"},{"value":"half","label":"Half iced"},{"value":"full","label":"Fully iced"}]},{"id":"clarity","type":"chips","label":"Clarity","required":false,"builtin":true,"showIf":{"field":"stones","in":["lab","natural"]},"options":[{"value":"SI","label":"SI"},{"value":"VS","label":"VS"},{"value":"VVS","label":"VVS"},{"value":"Flawless","label":"Flawless"}]}]},{"id":"budget","label":"Budget","title":"Your budget","subtitle":"So we design something that fits.","autoAdvance":true,"fields":[{"id":"budget","type":"chips","required":true,"big":true,"builtin":true,"ai":false,"options":[{"value":"Under $1,500","label":"Under $1,500"},{"value":"$1,500 - $2,500","label":"$1,500 - $2,500"},{"value":"$2,500 - $5,000","label":"$2,500 - $5,000"},{"value":"$5,000 - $10,000","label":"$5,000 - $10,000"},{"value":"$10,000 - $20,000","label":"$10,000 - $20,000"},{"value":"$20,000+","label":"$20,000+"}]}]},{"id":"vision","label":"Vision","title":"Describe your vision","subtitle":"Names, shapes, symbols, anything. The more detail, the better your preview.","fields":[{"id":"inscription","type":"text","label":"Name or text on the piece (optional)","placeholder":"e.g. Blake, J&M, 404","max":24,"builtin":true},{"id":"vision","type":"textarea","label":"Your idea","placeholder":"e.g. Script name pendant with a small crown over the first letter, iced out, about 2 inches tall","max":600,"builtin":true},{"id":"reference","type":"upload","label":"Inspiration photo (optional)","hint":"A screenshot or photo of something close to what you want.","builtin":true}]}]}', 'test-landing-page', 'custom-enquiry', 1792439734891);
